import React from 'react';
import AdHero from '../components/AdHero';
import AdStrip from '../components/AdStrip';

const Sports = () => {
    return (
        <div className="min-h-screen bg-white font-display">
            <AdHero page="sports" />
            <AdStrip page="sports" />

            <div className="max-w-[1440px] mx-auto py-16 px-6 lg:px-12 text-center">
                <h2 className="text-3xl font-extrabold text-[#10221c] uppercase tracking-tighter">Performance Sports</h2>
                <p className="text-gray-500 mt-4 max-w-2xl mx-auto">Engineered for excellence. High-performance gear that combines technical innovation with premium aesthetics.</p>
            </div>
        </div>
    );
};

export default Sports;
